func flow(ch chan int, input any, xs []int) int {
	total := 0
outer:
	for i := 0; i < len(xs); i++ {
		if xs[i] < 0 { continue outer } else { total += xs[i] }
	}
	for _, value := range xs { total += value }
	for range 3 { break }
	switch value := input.(type) {
	case int, string: _ = value
	default:
	}
	switch total {
	case 0: fallthrough
	default: total++
	}
	select {
	case ch <- total:
	case value := <-ch: total = value
	default:
	}
	go close(ch)
	defer func() { recover() }()
	goto done
done:
	return total
}

